<script type="module">
import * as THREE from 'three';

const W = 240, H = 294, TAU = 2 * Math.PI;
const renderer = new THREE.WebGLRenderer({ preserveDrawingBuffer: true });
renderer.setPixelRatio(1);
renderer.setSize(W, H, false);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0xfffefe);
const ref = new THREE.OrthographicCamera(-120, 120, 147, -147, 0.1, 1600);
ref.position.set(22, 147, 600);
ref.lookAt(22, 147, 0);
ref.updateMatrixWorld();

const grain = `
  vec3 stipple(vec2 pixel, float amount) {
    vec2 p = floor(pixel);
    float a = mod(p.x + 2.0*p.y, 4.0);
    float b = mod(2.0*p.x + p.y + floor(p.y/4.0), 5.0);
    float fleck = fract(52.9829189 * fract(dot(p,vec2(.06711056,.00583715))))-.5;
    float chroma = (a-1.5)/1.5;
    float value = (b-2.)*.012 + fleck*.032;
    return amount*(vec3(.058,.008,-.082)*chroma + value);
  }
`;

const backdrop = new THREE.Mesh(
  new THREE.PlaneGeometry(2, 2),
  new THREE.ShaderMaterial({
    depthTest: false, depthWrite: false,
    vertexShader: `
      void main() { gl_Position = vec4(position.xy, .99999, 1.); }
    `,
    fragmentShader: `
      precision highp float;
      ${grain}
      void main() {
        vec2 p=vec2(gl_FragCoord.x,294.-gl_FragCoord.y);
        float y=p.y;
        vec3 c=mix(vec3(.83,.835,.81), vec3(.852,.887,.966),smoothstep(-2.,14.,y));
        c=mix(c,vec3(.906,.92,.989),smoothstep(15.,50.,y));
        c=mix(c,vec3(.956,.935,.992),smoothstep(51.,63.,y));
        c=mix(c,vec3(1.,.999,.993),smoothstep(62.,78.,y));
        c=mix(c,vec3(.944,.951,.997),smoothstep(218.,242.,y));
        c=mix(c,vec3(.861,.859,.813),smoothstep(243.,264.,y));
        c=mix(c,vec3(.715,.72,.732),smoothstep(263.,297.,y));
        vec2 q=(p-vec2(82.,305.))/vec2(98.,30.);
        c-=.055*exp(-dot(q,q));
        float haze=.8+.2*sin(p.x*.034+y*.019);
        float paper=.10+.90*(1.-smoothstep(50.,83.,y)+smoothstep(218.,272.,y));
        c+=stipple(gl_FragCoord.xy,paper*haze);
        gl_FragColor=vec4(clamp(c,0.,1.),1.);
      }
    `
  })
);
backdrop.name = 'Pale studio background';
backdrop.frustumCulled = false;
backdrop.renderOrder = -1000;
scene.add(backdrop);

const skin = new THREE.ShaderMaterial({
  vertexColors: true,
  vertexShader: `
    varying vec3 pigment;
    varying vec3 worldNormal;
    varying vec3 viewDirection;
    void main() {
      vec4 mv=modelViewMatrix*vec4(position,1.);
      pigment=color;
      worldNormal=normalize(normalMatrix*normal)*mat3(viewMatrix);
      viewDirection=(isOrthographic ? vec3(0.,0.,1.) : normalize(-mv.xyz))*mat3(viewMatrix);
      gl_Position=projectionMatrix*mv;
    }
  `,
  fragmentShader: `
    precision highp float;
    varying vec3 pigment;
    varying vec3 worldNormal;
    varying vec3 viewDirection;
    ${grain}
    void main() {
      vec3 n=normalize(worldNormal), v=normalize(viewDirection);
      vec3 key=normalize(vec3(-.43,.83,.59));
      vec3 fill=normalize(vec3(.83,.38,.52));
      float k=max(dot(key,n),0.), f=max(dot(fill,n),0.);
      float light=.777+.106*n.y+.205*k+.127*f+.023*n.z;
      vec3 c=pigment*vec3(light+.012,light,light-.015);
      float sheen=pow(max(dot(n,normalize(key+v)),0.),13.);
      float rim=pow(1.-clamp(dot(n,v),0.,1.),2.5)*
        max(dot(n,normalize(vec3(.88,.48,-.19))),0.);
      c+=vec3(.055,.052,.035)*sheen*(.35+.65*pigment.r);
      c=mix(c,vec3(1.,.935,.718),rim*.33);
      c+=stipple(gl_FragCoord.xy,.56);
      gl_FragColor=vec4(clamp(c,0.,1.),1.);
    }
  `
});
skin.name = 'Soft golden skin';

const clamp = (x,a=0,b=1) => Math.min(b,Math.max(a,x));
const mix = (a,b,t) => a+(b-a)*t;
const blend = (a,b,t) => a.map((v,i)=>mix(v,b[i],t));
function smooth(a,b,x) {
  const t=clamp((x-a)/(b-a));
  return t*t*(3-2*t);
}
function spot(x,y,cx,cy,rx,ry) {
  return Math.exp(-((x-cx)/rx)**2 - ((y-cy)/ry)**2);
}
function palette(table,y) {
  let i=0;
  while(i<table.length-2 && y>table[i+1][0]) i++;
  const a=table[i], b=table[i+1];
  return blend(a.slice(1),b.slice(1),smooth(a[0],b[0],y));
}

// A profile row contains a longitudinal coordinate followed by section dimensions.
function section(table,y) {
  let i=0;
  while(i<table.length-2 && y>table[i+1][0]) i++;
  const a=table[i], b=table[i+1], p=table[Math.max(0,i-1)], q=table[Math.min(table.length-1,i+2)];
  const d=b[0]-a[0], t=clamp((y-a[0])/d), t2=t*t, t3=t2*t;
  return a.slice(1).map((v,k)=>{
    const j=k+1;
    const m=(b[j]-p[j])*d/(b[0]-p[0]);
    const n=(q[j]-a[j])*d/(q[0]-a[0]);
    return (2*t3-3*t2+1)*v+(t3-2*t2+t)*m+
           (-2*t3+3*t2)*b[j]+(t3-t2)*n;
  });
}

const character = new THREE.Group();
character.name = 'Golden pear-shaped creature';
scene.add(character);
const designPoint = (x,y,z) => new THREE.Vector3(x-98,294-y,z);
function pivot(parent,name,x,y,z) {
  const g=new THREE.Group();
  g.name=name;
  g.position.copy(parent.worldToLocal(designPoint(x,y,z)));
  parent.add(g);
  return g;
}
const torso=pivot(character,'Torso and belly',99,181,5);
const head=pivot(torso,'Head',98,61,1);
const face=pivot(head,'Face',102,42,18);
const eyes=pivot(face,'Eyes and lids',102,37,18);
const mouth=pivot(face,'Mouth',103,49,22);
const hips=pivot(character,'Hips',99,211,3);

// Closed section loops, with normals taken from the continuous surface.
function surface(parent,name,u0,u1,rows,sides,point,color) {
  const pos=[],norm=[],col=[],index=[];
  const origin=parent.getWorldPosition(new THREE.Vector3());
  const eu=(u1-u0)*.00013, ea=.001;
  for(let j=0;j<=rows;j++){
    const u=mix(u0,u1,j/rows);
    for(let i=0;i<sides;i++){
      const a=TAU*i/sides;
      const p=point(u,a);
      const d0=point(Math.max(u0,u-eu),a), d1=point(Math.min(u1,u+eu),a);
      const e0=point(u,a-ea), e1=point(u,a+ea);
      const dy=new THREE.Vector3(d1[0]-d0[0],d0[1]-d1[1],d1[2]-d0[2]);
      const da=new THREE.Vector3(e1[0]-e0[0],e0[1]-e1[1],e1[2]-e0[2]);
      const n=dy.cross(da).normalize();
      pos.push(p[0]-98-origin.x,294-p[1]-origin.y,p[2]-origin.z);
      norm.push(n.x,n.y,n.z);
      const c=color(p,u,a);
      col.push(c[0]/255,c[1]/255,c[2]/255);
      if(j<rows){
        const k=j*sides+i, h=j*sides+(i+1)%sides;
        index.push(k,k+sides,h+sides,k,h+sides,h);
      }
    }
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
  geo.setAttribute('normal',new THREE.Float32BufferAttribute(norm,3));
  geo.setAttribute('color',new THREE.Float32BufferAttribute(col,3));
  geo.setIndex(index);
  geo.computeBoundingSphere();
  const mesh=new THREE.Mesh(geo,skin);
  mesh.name=name;
  parent.add(mesh);
  return mesh;
}

const trunkProfile=[
  // Image height, section center x, half width, center depth, half depth.
  [17.8,101,.045,.4,.05],[18.7,101.0,6.7,.5,7.0],
  [21.5,101.0,12.5,.8,12.0],[26,100.9,17.0,1.3,16.0],
  [32,100.5,20.0,2.1,18.3],[39.5,99.5,22.25,2.4,19.45],
  [47.5,97.8,25.0,1.7,20.7],[58,96.4,29.5,-.3,22.3],
  [69,94.8,34.05,-1.7,24.0],[81,94.8,38.1,-2.0,26.5],
  [96,95.9,41.3,.0,30.7],[110,97,44.6,2.8,35.4],
  [125,98.3,48.6,6.0,40.5],[141,99.2,52.9,8.7,44.8],
  [157,99.7,56.15,10.45,47.0],[170,99.8,56.75,10.6,46.85],
  [183,99.8,54.95,9.6,44.1],[196,99.65,50.65,7.4,40.3],
  [210,99.3,44.55,4.6,35.4],[224,99.0,39.55,2.1,31.0]
];

function faceRelief(x,y){
  if(y>70) return 0;
  return 2.4*spot(x,y,91.2,34.7,8.0,3.5)+
         2.0*spot(x,y,111.7,34.3,6.7,3.1)-
         1.25*spot(x,y,91.3,38.5,6.8,2.1)-
         1.05*spot(x,y,112.5,38.0,5.7,2.0)+
         2.7*spot(x,y,103.5,39.7,5.6,6.3)+
         4.4*spot(x,y,103.2,45.7,11.4,4.2)+
         1.65*spot(x,y,102,52.2,10.9,4.0)+
         1.2*spot(x,y,86.5,45,5.5,6.8);
}
function frontDepth(x,y){
  const [cx,rx,cz,rz]=section(trunkProfile,y);
  const c=Math.sqrt(Math.max(.0001,1-((x-cx)/rx)**2));
  return cz+rz*c+faceRelief(x,y)*smooth(0,.65,c);
}
function core(y,a){
  const [cx,rx,cz,rz]=section(trunkProfile,y);
  const sn=Math.sin(a), cs=Math.cos(a), t=Math.acos(clamp(cs,-1,1));
  const split=smooth(193,224,y);
  const x=cx+rx*mix(sn, Math.sign(sn)*(.5-.5*Math.cos(2*t)),split);
  let z=cz+mix(rz*cs,22.6*Math.sin(2*t),split);
  if(y<70) z+=faceRelief(x,y)*smooth(0,.65,cs);
  return [x,y,z];
}
const hidePalette=[
  [17,250,207,54],[28,245,196,43],[38,229,177,44],
  [50,234,171,47],[60,234,158,48],[69,243,171,49],
  [82,255,193,43],[102,255,206,66],[127,254,202,96],
  [150,243,191,88],[169,239,181,71],[194,242,177,46],
  [214,235,164,50],[224,230,158,51],[251,221,147,48],
  [284,213,139,48],[316,199,131,48]
];
function coreColor(p,y,a){
  const [x,,z]=p, front=smooth(-.18,.87,Math.cos(a));
  let c=palette(hidePalette,y);
  if(y<65){
    const lid=spot(x,y,90,37,8.4,3.4)+.86*spot(x,y,113,37,7,3.1);
    c=blend(c,[188,157,45],clamp(lid*.58*front));
    c=blend(c,[197,130,47],.44*front*spot(x,y,104,53,16,6.8));
  }
  if(y>76){
    const bib=spot(x,y,110,133,62,33)*smooth(-.26,.66,Math.cos(a));
    c=blend(c,[255,221,185],.92*bib);
    c=blend(c,[255,240,181],.55*front*spot(x,y,96,112,33,16));
    c=blend(c,[242,191,154],.40*front*spot(x,y,132,146,29,23));
    c=blend(c,[208,159,80],.24*front*spot(x,y,99,169,45,11));
    const crease=smooth(195,228,y)*Math.exp(-((x-99)/6.4)**2);
    c=blend(c,[139,86,36],crease*.86);
  }
  const warmth=1.4*Math.sin(x*.095+y*.033+z*.061)*Math.sin(y*.105-x*.019);
  return [c[0]+warmth,c[1]+warmth*.7,c[2]];
}
surface(head,'Crown, cheeks and chin',17.8,61,82,112,core,coreColor);
surface(torso,'Shoulders, breast and abdomen',61,224,100,112,core,coreColor);

for(const side of [-1,1]){
  const left=side<0, label=left?'Left':'Right';
  const start=99+side*39.55/2;
  const leg=pivot(hips,label+' leg',start,221,2);
  const foot=pivot(leg,label+' foot',left?85:115,297,2);
  const prof=[
    [224,start,39.55/2,2.1,22.6],
    [233,left?79.7:118.9,left?18.85:18.90,1.8,22],
    [247,left?80.8:118.0,left?16.85:17.0,1.25,20.1],
    [264,left?82.6:116.9,left?14.4:15.15,.35,17.9],
    [280,left?84.0:115.9,left?12.8:13.6,-.1,16.1],
    [294,left?84.9:115.1,left?11.85:12.75,-.3,15.2],
    [299,left?84.8:115.3,left?11.85:12.8,1.2,16.1],
    [305,left?84.1:116.2,left?12.8:13.5,6.9,21.0],
    [309,left?83.7:116.4,left?12.4:13.1,8.9,21.6],
    [312,left?83.7:116.4,10.0,9.1,17.9],
    [313.3,left?83.7:116.4,.04,9.2,.07]
  ];
  const form=(y,a)=>{
    const [x,rx,z,rz]=section(prof,y);
    return [x+rx*Math.sin(a),y,z+rz*Math.cos(a)];
  };
  const pigment=(p,y,a)=>{
    let c=palette(hidePalette,y);
    const inside=clamp(-side*Math.sin(a));
    const contact=.78*Math.pow(inside,5)*Math.exp(-Math.max(y-224,0)/68);
    return blend(c,[133,80,33],contact);
  };
  surface(leg,label+' thigh and calf',224,298,47,56,form,pigment);
  surface(foot,label+' rounded foot',298,313.3,21,56,form,pigment);
}

// Curved elliptical sweeps keep the palms and individual digits volumetric.
function sweep(parent,name,knots,pigment,rows=32,sides=24){
  const data=knots.map((p,i)=>[i,...p]);
  function sample(u,a){
    const v=section(data,u);
    const lo=section(data,Math.max(0,u-.002));
    const hi=section(data,Math.min(knots.length-1,u+.002));
    const t=new THREE.Vector3(hi[0]-lo[0],hi[1]-lo[1],hi[2]-lo[2]).normalize();
    const lateral=new THREE.Vector3(t.y,-t.x,0).normalize();
    const front=lateral.clone().cross(t).normalize();
    const l=v[3]*Math.sin(a), d=v[4]*Math.cos(a);
    return [v[0]+l*lateral.x+d*front.x,v[1]+l*lateral.y+d*front.y,
            v[2]+l*lateral.z+d*front.z];
  }
  return surface(parent,name,0,knots.length-1,rows,sides,sample,pigment);
}

const armPalette=[
  [63,246,179,42],[80,246,191,44],[95,238,185,45],[113,238,189,65],
  [135,225,179,71],[154,204,158,63],[168,170,132,52],
  [179,120,98,48],[188,78,68,44],[197,60,55,41],[221,65,60,42]
];
for(const side of [-1,1]){
  const left=side<0, label=left?'Left':'Right';
  const arm=pivot(torso,label+' arm',left?66:127,left?71:72,-4);
  const fore=pivot(arm,label+' forearm',left?45.2:148.8,148,2);
  const hand=pivot(fore,label+' hand',left?38.9:154.5,left?179:184,left?9:4);
  const upper=left?[
    [70.2,64,-5,.12,.18],[66.2,70,-4,5.25,7.3],[60.7,80,-4.7,7.2,9],
