    [146.6,133,-3.7,3.95,5.2],[149.1,149,-1.9,4.05,5.15]
  ];
  const lower=left?[
    upper[upper.length-1],[43.15,159,5.05,4.45,5.15],[40.9,170.5,7,4.15,4.85],
    [38.9,179.5,9.1,3.85,4.4],[37.3,185.5,10.5,3.65,4.0]
  ]:[
    upper[upper.length-1],[151.25,162,-.2,4.2,5.1],[153.1,174.4,2.3,4.05,4.8],
    [155.25,184.1,4.55,3.65,4.2],[157.0,190.2,6.35,3.55,3.95]
  ];
  const armColor=(p,u,a)=>{
    let c=palette(armPalette,p[1]-(left?0:4));
    const inner=clamp(-side*Math.sin(a))*.22*smooth(103,152,p[1]);
    return blend(c,[113,91,44],inner);
  };
  sweep(arm,label+' upper arm',upper,armColor,52,32);
  sweep(fore,label+' lower arm',lower,armColor,32,32);
  const palm=left?[
    [38.6,180.2,9.15,3.1,3.65],[37.45,185.8,10.6,4.15,4.55],
    [35.05,191.9,12.45,5.3,4.9],[33.2,196.65,13.3,6.05,4.6],
    [32.65,200.0,13.8,4.95,3.6],[32.7,202.2,14.1,1.1,1.0]
  ]:[
    [154.9,184.8,4.6,3.15,3.7],[157.1,190.4,6.5,4.25,4.55],
    [160.25,196.1,8.7,5.3,4.7],[162.6,201.3,10.0,6.0,4.3],
    [163.25,204.8,10.8,4.85,3.4],[163.4,206.9,11.2,1.0,1.05]
  ];
  sweep(hand,label+' palm',palm,armColor,30,32);
  const digitPaths=[
    [[29.1,195.3,12.8],[26.75,200.7,13.7],[25.65,206.5,15.1],[26.05,211.1,16.4]],
    [[31.4,197.9,14.1],[29.65,204.2,15.0],[29.05,210.65,16.35],[29.75,215.0,17.45]],
    [[34.1,198.25,14.4],[33.0,204.4,15.55],[32.85,210.95,16.65],[33.65,214.5,18.25]],
    [[36.65,196.8,14.5],[36.35,202.25,16.0],[36.8,207.7,17.4],[37.8,211.25,18.6]],
    [[39.05,189.5,12.9],[40.15,193.35,15.8],[41.2,198.6,17.9],[40.6,203.5,18.8]]
  ];
  const names=['Little finger','Ring finger','Middle finger','Index finger','Thumb'];
  digitPaths.forEach((path,i)=>{
    const pts=path.map(([x,y,z])=>left?[x,y,z]:[
      195.55-x+(y-196)*.02,y+5.55+(i===0?.45:0),z-3.1
    ]);
    const fingers=pivot(hand,names[i],...pts[0]);
    const r=[1.72,1.96,2.0,1.83,2.18][i];
    const last=pts[3], prev=pts[2];
    const almost=prev.map((v,j)=>mix(v,last[j],.80));
    const knots=[
      [...pts[0],r*.85,r*.98],[...pts[1],r,r*1.05],
      [...prev,r*.77,r*.89],[...almost,r*.55,r*.63],[...last,.055,.08]
    ];
    const fingerColor=(p,u,a)=>{
      const tip=smooth(2.62,4,u);
      return blend([59+i,55+i,40+i],[111,97,62],tip*.79+.05*Math.cos(a));
    };
    sweep(fingers,names[i]+' skin',knots,fingerColor,23,16);
  });
}

// Small lenticular folds laid along the actual curvature of the face.
function fold(parent,name,x0,x1,line,height,depth,lift,pigment){
  const point=(u,a)=>{
    const x=mix(x0,x1,u);
    const taper=.012+.988*Math.pow(Math.max(0,Math.sin(Math.PI*u)),.7);
    const y=line(u)-height*taper*Math.sin(a);
    const z=frontDepth(x,y)+taper*(lift+depth*Math.cos(a));
    return [x,y,z];
  };
  return surface(parent,name,0,1,32,18,point,pigment);
}
for(const left of [true,false]){
  const x0=left?84.7:108.3, x1=left?96.65:118.0;
  const y0=left?37.3:36.85;
  const lid=pivot(eyes,left?'Left eyelids':'Right eyelids',(x0+x1)/2,y0,19);
  const curve=u=>y0+.67*Math.sin(Math.PI*u)+(left?.38:-.22)*(u-.5);
  fold(lid,'Lower lid',x0+.15,x1, u=>curve(u)+.65,.68,.48,.14,
    ()=>[223,176,53]);
  fold(lid,'Narrow eye opening',x0,x1,curve,.39,.39,.40,
    (p,u)=>blend([199,164,53],[140,124,49],.82*Math.sin(Math.PI*u)));
  fold(lid,'Upper lid',x0-.25,x1+.15,u=>curve(u)-.94,1.15,.78,.13,
    (p,u,a)=>blend([220,172,44],[238,189,52],.35+.35*Math.sin(a)));
}

const mouthLine=u=>48.95+.67*Math.sin(Math.PI*u)+.53*(u-.5);
fold(mouth,'Lower lip',92.1,114.2,u=>mouthLine(u)+1.08,1.16,.88,.13,
  ()=>[222,160,57]);
